  function choosePrompt(prompt:string){setText(prompt);composer.current?.focus()}
  function openMatter(id:string){setMatterId(id);setWorkTab('Overview');navigate('Work')}
  function openAttention(item:AttentionItem){if(item.matterId){openMatter(item.matterId);setWorkTab(item.kind==='obligation'?'Obligations':item.kind==='effect'?'Approvals & delivery':item.kind==='counsel'?'Counsel':'Overview')}else{setCompanyTab('Legal coverage');navigate('Company')}}
  function artifact(id:string){if(data?.scenarios.some(x=>x.id===id)){const next=data.scenarios.find(x=>x.id===id)!;setScenarioId(id);setAssumptions(next.assumptions.join('\n'));navigate('Kiara')}else if(data?.matters.some(x=>x.id===id))openMatter(id);else if(data?.documents.some(x=>x.id===id))open({kind:'document',document:data.documents.find(x=>x.id===id)!});else navigate('Company')}
