        {workTab==='Precedents'&&<ScopedPrecedentsPanel data={data} busy={busy||!!pending||!!uploadAttempt||!!emailAttempt} submit={submit} originMatterId={matter.id} openMatter={openMatter} openDocument={id=>{const document=data.documents.find(x=>x.id===id);if(document)open({kind:'document',document})}}/>}
