        {companyTab==='Preferences'&&<div className={s.twoColumns}><div className={s.card}><h2>Make this feel like working with you.</h2><p>Personal preferences affect your responses. Team routing requires the appropriate delegation.</p><label className={s.field}>Answer length<select value={data.preferences.find(p=>p.key==='response_length'&&p.ownerId===data.actor.id&&p.active)?.value??'balanced'} disabled={busy} onChange={e=>void submit({type:'preference.set',key:'response_length',value:e.target.value,target:'personal'})}><option value="balanced">Enough detail to decide</option><option value="short">Short answer first</option><option value="detailed">Explain in detail</option></select></label><label className={s.field}>Attention preference<select value={data.preferences.find(p=>p.key==='interruptions'&&p.ownerId===data.actor.id&&p.active)?.value??'decisions'} disabled={busy} onChange={e=>void submit({type:'preference.set',key:'interruptions',value:e.target.value,target:'personal'})}><option value="decisions">Only when I need to decide</option><option value="digest">Prefer a digest</option><option value="all">Include work updates</option></select><small>Required escalations still follow workspace authority and deadline policy.</small></label></div><div className={s.card}><h3>Your saved preferences</h3>{data.preferences.filter(p=>p.active).map(p=><div className={s.task} key={p.id}><div><h3>{human(p.key)}</h3><small>{p.value} · {p.target} · {p.ownerId}</small></div></div>)}</div></div>}
